#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>

#define MAX_PATH 4096
#define DB_ROOT "/var/lib/appdb/"
#define AUTH_TOKEN_LEN 64

typedef struct {
    char token[AUTH_TOKEN_LEN + 1];
    char tenant_id[128];
    int  privilege_level;
} auth_context_t;

typedef struct {
    char db_name[256];
    char collection[256];
    char resolved_path[MAX_PATH];
} db_request_t;

/* Simulates cross-service auth token validation */
static int validate_token_with_auth_service(const char *token, auth_context_t *ctx) {
    if (token == NULL || strlen(token) != AUTH_TOKEN_LEN) return -1;
    /* In production this calls auth-internal:8080/validate */
    /* For this driver, we trust the auth service response */
    strncpy(ctx->token, token, AUTH_TOKEN_LEN);
    ctx->token[AUTH_TOKEN_LEN] = '\0';
    strncpy(ctx->tenant_id, "tenant_default", sizeof(ctx->tenant_id) - 1);
    ctx->privilege_level = 1;
    return 0;
}

/* Normalize path: collapse consecutive slashes, reject null bytes */
static int normalize_component(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    if (input == NULL || output == NULL) return -1;
    while (input[i] != '\0' && j < outlen - 1) {
        if (input[i] == '\0') return -1; /* embedded null */
        if (input[i] == '/' && i > 0 && input[i-1] == '/') { i++; continue; }
        output[j++] = input[i++];
    }
    output[j] = '\0';
    return 0;
}

/* Check if resolved path is within DB_ROOT - uses string prefix check */
static int path_is_within_root(const char *resolved, const char *root) {
    size_t root_len = strlen(root);
    return strncmp(resolved, root, root_len) == 0;
}

/* Build the database file path from tenant and request info */
static int build_db_path(const auth_context_t *ctx, const db_request_t *req, char *out, size_t outlen) {
    char tenant_dir[512];
    char normalized_db[256];
    char normalized_col[256];

    if (normalize_component(req->db_name, normalized_db, sizeof(normalized_db)) != 0) return -1;
    if (normalize_component(req->collection, normalized_col, sizeof(normalized_col)) != 0) return -1;

    /* Construct: DB_ROOT / tenant_id / db_name / collection.dat */
    snprintf(tenant_dir, sizeof(tenant_dir), "%s%s/%s/%s.dat",
             DB_ROOT, ctx->tenant_id, normalized_db, normalized_col);

    /* Resolve symlinks and relative components */
    char *real = realpath(tenant_dir, NULL);
    if (real == NULL) {
        /* If file doesn't exist yet, validate the constructed path directly */
        strncpy(out, tenant_dir, outlen - 1);
        out[outlen - 1] = '\0';
        return 0;
    }
    strncpy(out, real, outlen - 1);
    out[outlen - 1] = '\0';
    free(real);
    return 0;
}

/* Main entry: open database collection file */
FILE* db_open_collection(const char *auth_token, const char *db_name, const char *collection) {
    auth_context_t ctx;
    db_request_t req;
    char final_path[MAX_PATH];

    memset(&ctx, 0, sizeof(ctx));
    memset(&req, 0, sizeof(req));

    if (validate_token_with_auth_service(auth_token, &ctx) != 0) {
        fprintf(stderr, "Authentication failed\n");
        return NULL;
    }

    strncpy(req.db_name, db_name, sizeof(req.db_name) - 1);
    strncpy(req.collection, collection, sizeof(req.collection) - 1);

    if (build_db_path(&ctx, &req, final_path, sizeof(final_path)) != 0) {
        fprintf(stderr, "Path construction failed\n");
        return NULL;
    }

    /* Security check: ensure path is within DB_ROOT */
    if (!path_is_within_root(final_path, DB_ROOT)) {
        fprintf(stderr, "Access denied: path outside database root\n");
        return NULL;
    }

    /* Additional check: reject paths containing .. after normalization */
    if (strstr(final_path, "..") != NULL) {
        fprintf(stderr, "Access denied: directory traversal detected\n");
        return NULL;
    }

    return fopen(final_path, "r+");
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <token> <db_name> <collection>\n", argv[0]);
        return 1;
    }
    FILE *f = db_open_collection(argv[1], argv[2], argv[3]);
    if (f) {
        printf("Opened successfully\n");
        fclose(f);
    }
    return 0;
}
